CREATE OR REPLACE FUNCTION coordinate_legacy_push_token_update() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE lock_key text; BEGIN IF NEW.is_deleted = false AND (NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.type IS DISTINCT FROM OLD.type OR NEW.name IS DISTINCT FROM OLD.name OR NEW.client_device_id IS DISTINCT FROM OLD.client_device_id OR NEW.first_seen_at IS DISTINCT FROM OLD.first_seen_at OR NEW.last_seen_at IS DISTINCT FROM OLD.last_seen_at OR NEW.is_deleted IS DISTINCT FROM OLD.is_deleted OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at OR NEW.deleted_by_id IS DISTINCT FROM OLD.deleted_by_id) THEN NEW.push_token := OLD.push_token; RETURN NEW; END IF;
PERFORM pg_advisory_xact_lock( hashtextextended('push-token:mutations'::text, 0));
FOR lock_key IN SELECT DISTINCT candidate FROM (VALUES (CASE WHEN OLD.push_token IS NULL THEN NULL ELSE 'push-token:value:' || OLD.push_token END), (CASE WHEN NEW.push_token IS NULL THEN NULL ELSE 'push-token:value:' || NEW.push_token END) ) AS token_locks(candidate) WHERE candidate IS NOT NULL ORDER BY candidate LOOP PERFORM pg_advisory_xact_lock(hashtextextended(lock_key::text, 0)); END LOOP;
IF NEW.push_token IS NOT NULL THEN UPDATE devices SET push_token = NULL, updated_at = now() WHERE id <> NEW.id AND is_deleted = false AND push_token = NEW.push_token; END IF; RETURN NEW; END; $$;

UPDATE devices SET push_token = NULL, updated_at = now() WHERE push_token IS NOT NULL AND (is_deleted = true OR btrim(push_token) = '');
WITH duplicate_tokens AS ( SELECT push_token FROM devices WHERE is_deleted = false AND push_token IS NOT NULL GROUP BY push_token HAVING count(*) > 1 ) UPDATE devices device SET push_token = NULL, updated_at = now() FROM duplicate_tokens duplicate WHERE device.is_deleted = false AND device.push_token = duplicate.push_token;
CREATE UNIQUE INDEX uk_devices_push_token_active ON devices (push_token) WHERE is_deleted = false AND push_token IS NOT NULL;

CREATE OR REPLACE FUNCTION scrub_push_notification_token_snapshot()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.channel = 'PUSH' THEN
        NEW.destination_push_token := NULL;
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION coordinate_legacy_account_anonymization_start()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    subject_id uuid;
BEGIN
    IF NEW.step <> 'STARTED' THEN
        RETURN NEW;
    END IF;

    SELECT coalesce(request.subject_id, request.user_id)
      INTO subject_id
      FROM account_deletion_requests request
     WHERE request.id = NEW.request_id;

    IF subject_id IS NULL THEN
        RETURN NEW;
    END IF;

    PERFORM pg_advisory_xact_lock(
        hashtextextended('push-token:mutations'::text, 0));
    PERFORM pg_advisory_xact_lock(
        hashtextextended(('push-token:user:' || subject_id::text)::text, 0));
    RETURN NEW;
END;
$$;
